-- Lab third-party requisition lines. Fusion fields first, EBS as fallback. {START} as in orders.sql. Keep in step with TP_SQL in src/page.html.
SELECT "Party Name" V, "Requisition Number" R, "Requester Name" RQ, LEFT(COALESCE(NULLIF("Fusion GL Dept Code",''),"EBS GL Dept Code"),4) D, COALESCE(NULLIF("Fusion GL Acct Code",''),"EBS GL Acct Code") A, COALESCE(NULLIF("Fusion GL Acct Desc",''),"EBS GL Acct Desc") AD, "Amount" AMT, COALESCE(NULLIF("Invoice Currency Code",'0'),'Code 0') CCY, TO_CHAR(COALESCE("PR Approved Date","Creation Date")::DATE) DT, IFF("PR Approved Date" IS NULL,1,0) NA, COALESCE(NULLIF("Fusion Project Desc",''),"EBS Project Desc",'') PROJ FROM EDNA.CONS_INSIGHTS_MART.EDNA_PROCUREMENT WHERE LEFT(COALESCE(NULLIF("Fusion GL Dept Code",''),"EBS GL Dept Code"),4) IN ('7030','7110','7120','7130','7140') AND UPPER("Party Name") NOT LIKE '%EXTREME NETWORKS%' AND "Amount" IS NOT NULL AND COALESCE(NULLIF("Fusion GL Acct Code",''),"EBS GL Acct Code") IN ('20050','20020','20040','87100','87120','87140','87160','87165','89150','89170','89180','89260','89270') AND COALESCE("PR Approved Date","Creation Date") >= '{START}' ORDER BY DT DESC
